void Solver::bump_var(int var, double coeff) {
    // Compute the increment for this variable.
    double inc = var_inc * coeff;
    activity[var] += inc;

    // If activity grows too large, rescale all activities to avoid overflow.
    if (activity[var] > 1e80) {
        const double scale = 1e-80;
        for (int i = 1; i <= vars; ++i) activity[i] *= scale;
        var_inc *= scale;
    }

    // Keep the VSIDS heap consistent.
    // If the variable is already in the heap, update its position;
    // otherwise insert it (variables may have been removed during backtrack).
    if (vsids.inHeap(var)) {
        vsids.update(var);
    } else {
        vsids.insert(var);
    }
}
